<?php
declare(strict_types=1);namespace App\Command;use App\Imperium\Runtime\Curia\OperationalDeploymentAuthorizationService;use Symfony\Component\Console\Attribute\AsCommand;use Symfony\Component\Console\Command\Command;use Symfony\Component\Console\Input\InputArgument;use Symfony\Component\Console\Input\InputInterface;use Symfony\Component\Console\Input\InputOption;use Symfony\Component\Console\Output\OutputInterface;
#[AsCommand(name:'imperium:curia:authorize-operational-deployment',description:'Authorize one exact bound Manifestation for one bounded mission use.')]
final class CuriaAuthorizeOperationalDeploymentCommand extends Command{public function __construct(private readonly OperationalDeploymentAuthorizationService$s){parent::__construct();}protected function configure():void{$this->addArgument('binding-id',InputArgument::REQUIRED)->addArgument('seneschal-binding-id',InputArgument::REQUIRED)->addArgument('objective',InputArgument::REQUIRED)->addArgument('input-contract',InputArgument::REQUIRED)->addArgument('output-contract',InputArgument::REQUIRED)->addArgument('stop-condition',InputArgument::REQUIRED)->addOption('json',null,InputOption::VALUE_NONE);}protected function execute(InputInterface$i,OutputInterface$o):int{try{$r=$this->s->authorize((string)$i->getArgument('binding-id'),(string)$i->getArgument('seneschal-binding-id'),['objective'=>(string)$i->getArgument('objective'),'input_contract'=>(string)$i->getArgument('input-contract'),'output_contract'=>(string)$i->getArgument('output-contract'),'stop_condition'=>(string)$i->getArgument('stop-condition')]);}catch(\Throwable$e){$o->writeln('<error>REFUSED</error> '.$e->getMessage());return self::FAILURE;}$o->writeln($i->getOption('json')?json_encode($r,JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR):'<info>OPERATIONAL_DEPLOYMENT_AUTHORIZED</info> '.$r['authorization_id']);return self::SUCCESS;}}
